import ast,hashlib,json,sys
from pathlib import Path
R=Path.cwd();O=Path(__file__).parent;sys.path.insert(0,str(R))
from experiments.codex_dogfood.verification.spans import SourceSpans
from devtools.context.python.function.declarations import PythonSourceRange
from devtools.context.python.function.materialization import _extract_source_segment,PythonFunctionSourceMaterializationError
out=[]
for sep in ['\v','\f','\x1c','\x1d','\x1e','\x85','\u2028','\u2029']:
 for ending in ['\n','\r\n','\r']:
  text='"a'+sep+'b"'+ending+'x = 1'+ending
  name=ast.parse(text).body[1].targets[0];span=PythonSourceRange(name.lineno,name.col_offset,name.end_lineno,name.end_col_offset)
  expected=_extract_source_segment(text,span);actual=SourceSpans().extract(text,span)
  assert expected=='x' and actual=='b'
  out.append(dict(kind='VALID_NATIVE_AST_RANGE_MISMATCH',separator=hex(ord(sep)),newline=repr(ending),text=text,span=[span.start_line,span.start_column_utf8,span.end_line,span.end_column_utf8],expected=expected,actual=actual))
text='Î»x\n';span=PythonSourceRange(1,1,1,1)
try:_extract_source_segment(text,span)
except PythonFunctionSourceMaterializationError as e:message=str(e)
else:raise AssertionError('Canonical accepted invalid UTF8 column')
actual=SourceSpans().extract(text,span);assert actual==''
out.append(dict(kind='INVALID_UTF8_EMPTY_RANGE_ACCEPTED',text=text,span=[1,1,1,1],expected_error=message,actual=actual))
for text in ['', 'last line', 'Î»x\r\nabc\n']:
 for span in [PythonSourceRange(1,0,1,0),PythonSourceRange(1,0,1,2),PythonSourceRange(0,0,1,1)]:
  def result(f):
   try:return ('return',f(text,span))
   except (PythonFunctionSourceMaterializationError,UnicodeDecodeError) as e:return (type(e).__name__,str(e))
  expected=result(_extract_source_segment);actual=result(SourceSpans().extract);assert actual==expected,(text,span,expected,actual)
out.append(dict(kind='ORDINARY_BOUNDARY_CONTROLS',passed=9))
source=Path(__file__).read_text();value=dict(source=source,source_sha256=hashlib.sha256(source.encode()).hexdigest(),cases=out,confirmed_mismatches=25,controls_passed=9,scope='Independent native AST/UTF8 fixtures only; no archived data, pickle, capture, adjudication or historical verdict replay')
(O/'probes.json').write_text(json.dumps(value,ensure_ascii=True,indent=2)+'\n');print(json.dumps({k:v for k,v in value.items() if k not in ['source','cases']},indent=2))
